from dynamodb.entity.entity import Entity, EntityType


class TodoListEntity(Entity):
    entity_type = EntityType.TodoList

    def __init__(self, pk: str, sk: str, name: str):
        self.pk = pk
        self.sk = sk
        self.name = name

    @staticmethod
    def from_dict(data: dict):
        return TodoListEntity(
            pk=data.get('pk'),
            sk=data.get('sk'),
            name=data.get('name')
        )

    def to_dict(self):
        return {
            "pk": self.pk,
            "sk": self.sk,
            "name": self.name
        }
